SET ROLE talus_fn;
CREATE TABLE app.dispatch_record(tenant_id uuid NOT NULL,dispatch_record_id uuid NOT NULL,booking_item_id uuid NOT NULL,trip_id uuid NOT NULL,machine_id uuid NOT NULL,dispatched_by uuid NOT NULL,dispatched_at timestamptz NOT NULL,outbound_inspection_id uuid NOT NULL,starting_odometer_miles bigint,starting_fuel_pct integer,PRIMARY KEY(tenant_id,dispatch_record_id),FOREIGN KEY(tenant_id,booking_item_id) REFERENCES app.booking_item(tenant_id,booking_item_id),FOREIGN KEY(tenant_id,trip_id) REFERENCES app.trip(tenant_id,trip_id),FOREIGN KEY(tenant_id,machine_id) REFERENCES app.machine(tenant_id,machine_id),FOREIGN KEY(tenant_id,outbound_inspection_id) REFERENCES app.inspection(tenant_id,inspection_id));
CREATE TABLE app.return_record(tenant_id uuid NOT NULL,return_record_id uuid NOT NULL,booking_item_id uuid NOT NULL,trip_id uuid NOT NULL,machine_id uuid NOT NULL,received_by uuid NOT NULL,returned_at timestamptz NOT NULL,inbound_inspection_id uuid NOT NULL,ending_odometer_miles bigint,ending_fuel_pct integer,fuel_charge_cents bigint NOT NULL DEFAULT 0,excess_mileage_cents bigint NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,return_record_id),FOREIGN KEY(tenant_id,booking_item_id) REFERENCES app.booking_item(tenant_id,booking_item_id),FOREIGN KEY(tenant_id,trip_id) REFERENCES app.trip(tenant_id,trip_id),FOREIGN KEY(tenant_id,machine_id) REFERENCES app.machine(tenant_id,machine_id),FOREIGN KEY(tenant_id,inbound_inspection_id) REFERENCES app.inspection(tenant_id,inspection_id),CHECK(fuel_charge_cents>=0 AND excess_mileage_cents>=0));
CREATE TRIGGER m08_dispatch_append BEFORE UPDATE OR DELETE ON app.dispatch_record FOR EACH ROW EXECUTE FUNCTION app.enforce_append_only();
CREATE TRIGGER m08_return_append BEFORE UPDATE OR DELETE ON app.return_record FOR EACH ROW EXECUTE FUNCTION app.enforce_append_only();
CREATE OR REPLACE FUNCTION app.dispatch_booking_item(p_item uuid,p_occupancy uuid,p_outbound uuid,p_at timestamptz DEFAULT clock_timestamp()) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id();m uuid;tr uuid;BEGIN PERFORM app.require_staff_role('staff');SELECT machine_id INTO m FROM app.machine_occupancy WHERE tenant_id=t AND machine_occupancy_id=p_occupancy AND booking_item_id=p_item AND occupancy_kind='rental' AND blocking;IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM app.inspection WHERE tenant_id=t AND inspection_id=p_outbound AND booking_item_id=p_item AND inspection_type='outbound' AND status='completed') THEN RAISE EXCEPTION 'DISPATCH_GATE_FAILED' USING ERRCODE='P0001';END IF;SELECT app.open_core_trip(p_item,p_occupancy,(SELECT checkout_occurrence_id FROM app.checkout_occurrence WHERE tenant_id=t AND booking_item_id=p_item AND machine_occupancy_id=p_occupancy LIMIT 1),p_at) INTO tr;UPDATE app.booking_item SET state='checked_out' WHERE tenant_id=t AND booking_item_id=p_item;INSERT INTO app.dispatch_record VALUES(t,gen_random_uuid(),p_item,tr,m,app.current_context_principal_id(),p_at,p_outbound,NULL,NULL);PERFORM app.append_audit('booking_item.dispatched','booking_item',p_item);RETURN tr;END;$$;
CREATE OR REPLACE FUNCTION app.receive_booking_return(p_item uuid,p_trip uuid,p_inbound uuid,p_at timestamptz,p_fuel bigint DEFAULT 0,p_mileage bigint DEFAULT 0) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id();m uuid;BEGIN PERFORM app.require_staff_role('staff');SELECT machine_id INTO m FROM app.trip WHERE tenant_id=t AND trip_id=p_trip AND booking_item_id=p_item AND ended_at IS NULL;IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM app.inspection WHERE tenant_id=t AND inspection_id=p_inbound AND booking_item_id=p_item AND inspection_type='inbound' AND status='completed') THEN RAISE EXCEPTION 'RETURN_GATE_FAILED' USING ERRCODE='P0001';END IF;PERFORM app.seal_core_trip(p_trip,p_at);UPDATE app.booking_item SET state='returned' WHERE tenant_id=t AND booking_item_id=p_item;UPDATE app.machine_occupancy SET blocking=false WHERE tenant_id=t AND booking_item_id=p_item AND occupancy_kind='rental';INSERT INTO app.return_record VALUES(t,gen_random_uuid(),p_item,p_trip,m,app.current_context_principal_id(),p_at,p_inbound,NULL,NULL,p_fuel,p_mileage);PERFORM app.append_audit('booking_item.returned','booking_item',p_item);RETURN p_trip;END;$$;
DO $$ DECLARE x text;BEGIN FOREACH x IN ARRAY ARRAY['dispatch_record','return_record'] LOOP EXECUTE format('ALTER TABLE app.%I ENABLE ROW LEVEL SECURITY;ALTER TABLE app.%I FORCE ROW LEVEL SECURITY;CREATE POLICY tenant_context_policy ON app.%I USING(tenant_id=app.current_context_tenant_id() AND app.context_is_valid()) WITH CHECK(tenant_id=app.current_context_tenant_id() AND app.context_is_valid())',x,x,x);END LOOP;END;$$;
GRANT SELECT,INSERT,UPDATE,DELETE ON app.dispatch_record,app.return_record TO talus_fn;
REVOKE ALL ON app.dispatch_record,app.return_record FROM PUBLIC,talus_staff,talus_api,talus_customer;
RESET ROLE;
